<?php
require __DIR__.'/../../app/bootstrap.php';require_once __DIR__.'/../../app/api_v2.php';$u=api_v2_user('catalog');[$page,$per,$off]=api_v2_page();$type=(string)($_GET['type']??'products');$q=trim((string)($_GET['q']??''));if($type==='businesses'){$where='b.status=1';$p=[];if($q!==''){$where.=' AND (b.name LIKE ? OR b.description LIKE ? OR b.address LIKE ?)';$like='%'.$q.'%';$p=[$like,$like,$like];}$cnt=db()->prepare("SELECT COUNT(*) FROM businesses b WHERE $where");$cnt->execute($p);$total=(int)$cnt->fetchColumn();$st=db()->prepare("SELECT b.id,b.name,b.slug,b.address,b.phone,b.whatsapp,b.verification_status,b.image,c.name city_name,cat.name category_name FROM businesses b LEFT JOIN cities c ON c.id=b.city_id LEFT JOIN categories cat ON cat.id=b.category_id WHERE $where ORDER BY b.is_featured DESC,b.id DESC LIMIT $per OFFSET $off");$st->execute($p);$rows=$st->fetchAll();}else{$where="p.status='published'";$p=[];if($q!==''){$where.=' AND (p.title LIKE ? OR p.short_description LIKE ?)';$like='%'.$q.'%';$p=[$like,$like];}$cnt=db()->prepare("SELECT COUNT(*) FROM store_products p WHERE $where");$cnt->execute($p);$total=(int)$cnt->fetchColumn();$st=db()->prepare("SELECT p.id,p.title,p.slug,p.product_type,p.sale_mode,p.price,p.compare_price,p.stock,p.image_url,p.city_id,p.category_id,p.views FROM store_products p WHERE $where ORDER BY p.featured DESC,p.id DESC LIMIT $per OFFSET $off");$st->execute($p);$rows=$st->fetchAll();}api_v2_ok(['type'=>$type,'data'=>$rows,'meta'=>api_v2_meta($page,$per,$total)]);
